from collections import deque
def solve(I):
    H,W=len(I),len(I[0]); seen=[[False]*W for _ in range(H)]
    q=deque()
    # seed with 2s on border
    for i in range(H):
        for j in (0,W-1):
            if I[i][j]==2 and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if I[i][j]==2 and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and not seen[ni][nj] and I[ni][nj]==2:
                seen[ni][nj]=True; q.append((ni,nj))
    return [[4 if I[i][j]==2 and not seen[i][j] else I[i][j] for j in range(W)] for i in range(H)]
